import React from "react";
import { motion } from "framer-motion";

const statuses = [
  { key: "new", label: "Mới", color: "bg-blue-100 border-blue-300" },
  { key: "processing", label: "Đang xử lý", color: "bg-yellow-100 border-yellow-300" },
  { key: "converted", label: "Chuyển đổi", color: "bg-green-100 border-green-300" },
  { key: "lost", label: "Mất", color: "bg-red-100 border-red-300" },
];

const LeadKanban = ({ leads, onDragStart, onDrop, onDelete }) => {
  return (
    <div className="grid grid-cols-4 gap-4 p-4 bg-gray-50 rounded-xl">
      {statuses.map((status) => (
        <div
          key={status.key}
          className={`rounded-xl p-3 border ${status.color} shadow-sm`}
          onDragOver={(e) => e.preventDefault()}
          onDrop={() => onDrop(status.key)}
        >
          <h3 className="text-center font-semibold text-gray-700 mb-3">{status.label}</h3>
          <div className="flex flex-col gap-3 min-h-[400px]">
            {leads
              .filter((l) => l.status === status.key)
              .map((lead) => (
                <motion.div
                  key={lead._id}
                  layout
                  draggable
                  onDragStart={() => onDragStart(lead)}
                  whileHover={{ scale: 1.02 }}
                  className="bg-white p-3 rounded-lg shadow hover:shadow-md transition border border-gray-200"
                >
                  <div className="flex justify-between items-center mb-2">
                    <h4 className="font-semibold text-gray-800">{lead.name}</h4>
                    <button
                      onClick={() => onDelete(lead._id)}
                      className="text-red-500 hover:text-red-700 text-sm"
                    >
                      ✖
                    </button>
                  </div>
                  <p className="text-sm text-gray-600">{lead.email}</p>
                  <p className="text-sm text-gray-600">{lead.phone}</p>
                </motion.div>
              ))}
          </div>
        </div>
      ))}
    </div>
  );
};

export default LeadKanban;
